import React, { useState } from "react";
import axios from "axios";
import { useNavigate, useLocation } from "react-router-dom";

const UserDetails = () => {
  const navigate = useNavigate();
  const location = useLocation();
  const { houseId, selectedDate, amount } = location.state || {};
  const userId = localStorage.getItem("userId");

  const [formData, setFormData] = useState({
    name: "",
    phone: "",
    email: "",
    idProof: "",
    persons: 1,
  });
  const [otp, setOtp] = useState("");
  const [otpSent, setOtpSent] = useState(false);
  const [error, setError] = useState(null);
  const [isSending, setIsSending] = useState(false);
  const [isVerifying, setIsVerifying] = useState(false);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSendOtp = async () => {
    if (isSending) return;
    if (!formData.phone || !formData.email) {
      setError("Phone and email are required.");
      return;
    }

    setIsSending(true);
    setError(null);

    const phone = formData.phone.startsWith("+91")
      ? formData.phone
      : `+91${formData.phone}`;

    try {
      const response = await axios.post("http://localhost:5000/api/send-otp", {
        phone,
        email: formData.email,
        userId,
      });
      console.log("Send OTP Response:", response.data);
      if (response.data.success) {
        setOtpSent(true);
        alert(
          `OTP sent to your mobile number (${phone}) and email (${formData.email}). Please check your SMS and inbox (including spam/junk folder). It is valid for 10 minutes.`
        );
      } else {
        setError(response.data.error || "Failed to send OTP.");
      }
    } catch (err) {
      console.error("Send OTP Error:", err.message, err.response?.data);
      setError(
        err.response?.data?.error || "Failed to send OTP. Please try again."
      );
    } finally {
      setIsSending(false);
    }
  };

  const handleVerifyOtp = async () => {
    if (isVerifying) return;
    if (!otp) {
      setError("Please enter the OTP.");
      return;
    }

    setIsVerifying(true);
    setError(null);

    const phone = formData.phone.startsWith("+91")
      ? formData.phone
      : `+91${formData.phone}`;

    try {
      const response = await axios.post(
        "http://localhost:5000/api/verify-otp",
        {
          phone,
          otp,
          userId,
        }
      );
      console.log("Verify OTP Response:", response.data);
      if (response.data.success) {
        // Proceed with booking
        const bookingResponse = await axios.post(
          "http://localhost:5000/api/bookings",
          {
            houseId,
            userId,
            days: 1, // Assuming single-day booking; adjust if multiple days
            start_date: selectedDate, // e.g., "2025-04-27"
            amount,
            userDetails: formData,
          }
        );
        console.log("Booking Response:", bookingResponse.data);

        // Notify owner
        await axios.post("http://localhost:5000/api/owner/booking", {
          houseId,
          userId,
          userDetails: formData,
          selectedDates: [selectedDate],
        });

        console.log(
          "Navigating to /booking-confirmation/",
          bookingResponse.data.bookingId
        );
        navigate(`/booking-confirmation/${bookingResponse.data.bookingId}`);
      } else {
        setError(response.data.error || "Invalid OTP. Please try again.");
      }
    } catch (err) {
      console.error(
        "Verify OTP or Booking Error:",
        err.message,
        err.response?.data
      );
      setError(
        err.response?.data?.error ||
          "Failed to verify OTP or create booking. Please try again."
      );
    } finally {
      setIsVerifying(false);
    }
  };

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-100 p-6">
      <div className="bg-white p-8 rounded-lg shadow-lg w-full max-w-md">
        <h2 className="text-2xl font-bold mb-6 text-center">User Details</h2>
        {!otpSent ? (
          <div className="space-y-4">
            <div>
              <label className="block text-gray-700">Name</label>
              <input
                type="text"
                name="name"
                value={formData.name}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                required
                disabled={isSending}
              />
            </div>
            <div>
              <label className="block text-gray-700">Phone</label>
              <input
                type="text"
                name="phone"
                value={formData.phone}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                placeholder="+91877808XXXX"
                required
                disabled={isSending}
              />
            </div>
            <div>
              <label className="block text-gray-700">Email</label>
              <input
                type="email"
                name="email"
                value={formData.email}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                required
                disabled={isSending}
              />
            </div>
            <div>
              <label className="block text-gray-700">ID Proof</label>
              <input
                type="text"
                name="idProof"
                value={formData.idProof}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                required
                disabled={isSending}
              />
            </div>
            <div>
              <label className="block text-gray-700">Number of Persons</label>
              <input
                type="number"
                name="persons"
                value={formData.persons}
                onChange={handleChange}
                className="w-full p-2 border rounded"
                min="1"
                required
                disabled={isSending}
              />
            </div>
            <button
              onClick={handleSendOtp}
              className="w-full bg-blue-500 text-white p-2 rounded hover:bg-blue-600 disabled:bg-gray-400"
              disabled={isSending}
            >
              {isSending ? "Sending OTP..." : "Send OTP"}
            </button>
          </div>
        ) : (
          <div className="space-y-4">
            <div>
              <label className="block text-gray-700">Enter OTP</label>
              <input
                type="text"
                value={otp}
                onChange={(e) => setOtp(e.target.value)}
                className="w-full p-2 border rounded"
                required
                disabled={isVerifying}
              />
            </div>
            <button
              onClick={handleVerifyOtp}
              className="w-full bg-blue-500 text-white p-2 rounded hover:bg-blue-600 disabled:bg-gray-400"
              disabled={isVerifying}
            >
              {isVerifying ? "Verifying OTP..." : "Verify OTP"}
            </button>
            <button
              onClick={handleSendOtp}
              className="w-full bg-gray-500 text-white p-2 rounded hover:bg-gray-600 disabled:bg-gray-400"
              disabled={isSending || isVerifying}
            >
              {isSending ? "Sending OTP..." : "Resend OTP"}
            </button>
          </div>
        )}
        {error && <div className="text-red-500 mt-4">{error}</div>}
      </div>
    </div>
  );
};

export default UserDetails;
